import numpy as np
from scipy.optimize import linprog

def solve_linear_program(c, A_ub, b_ub, A_eq=None, b_eq=None):
    result = linprog(c, A_ub=A_ub, b_ub=b_ub, A_eq=A_eq, b_eq=b_eq, method='highs')

    if result.success:
        return {
            'optimal_value': result.fun,
            'solution': result.x,
            'status': 'optimal'
        }
    else:
        return {'status': 'infeasible or unbounded'}

def simplex_tableau(c, A, b):
    m, n = A.shape
    tableau = np.zeros((m + 1, n + m + 1))
    tableau[:m, :n] = A
    tableau[:m, n:n+m] = np.eye(m)
    tableau[:m, -1] = b
    tableau[-1, :n] = c

    for iteration in range(20):
        entering_col = np.argmin(tableau[-1, :-1])
        if tableau[-1, entering_col] >= 0:
            break

        ratios = np.where(tableau[:m, entering_col] > 0,
                         tableau[:m, -1] / tableau[:m, entering_col], np.inf)
        leaving_row = np.argmin(ratios)

        if ratios[leaving_row] == np.inf:
            return {'status': 'unbounded'}

        pivot_val = tableau[leaving_row, entering_col]
        tableau[leaving_row] /= pivot_val
        for i in range(m + 1):
            if i != leaving_row:
                factor = tableau[i, entering_col]
                tableau[i] -= factor * tableau[leaving_row]

    solution = np.zeros(n)
    for j in range(n):
        col = tableau[:-1, j]
        if np.sum(col == 1) == 1 and np.sum(col == 0) == m - 1:
            row_idx = np.argmax(col)
            solution[j] = tableau[row_idx, -1]

    return {'solution': solution, 'optimal_value': -tableau[-1, -1]}

c = np.array([-3, -2])
A_ub = np.array([[1, 1], [1, -1]])
b_ub = np.array([4, 2])

result = solve_linear_program(c, A_ub, b_ub)
print(f"Optimal value: {-result['optimal_value']}")
print(f"Solution: {result['solution']}")
